import sys
sys.path.insert(0, '/app/scripts')
import importlib.util

spec = importlib.util.spec_from_file_location('new_solr_updater', '/app/scripts/new-solr-updater.py')
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

find_keys = m.find_keys
parse_log = m.parse_log

# --- find_keys tests ---
doc = {
    "key": "/books/OL34239002M",
    "type": {"key": "/type/edition"},
    "works": [{"key": "/works/OL1W"}],
}
assert list(find_keys(doc)) == [
    "/books/OL34239002M",
    "/type/edition",
    "/works/OL1W",
], list(find_keys(doc))

# list input
assert list(find_keys([{"key": "/a"}, [{"key": "/b"}], "string", 5, None])) == ["/a", "/b"]

# non-string key value should not be emitted
assert list(find_keys({"key": None, "x": {"key": "/b"}})) == ["/b"]
assert list(find_keys({"key": 5})) == []
assert list(find_keys("not a dict")) == []
assert list(find_keys(42)) == []

print("find_keys OK")

# --- parse_log: edition moved from work 1 to work 2 ---
record = {
    "action": "save",
    "data": {
        "changeset": {
            "docs": [
                {
                    "key": "/books/OL34239002M",
                    "type": {"key": "/type/edition"},
                    "works": [{"key": "/works/OL2W"}],
                }
            ],
            "old_docs": [
                {
                    "key": "/books/OL34239002M",
                    "type": {"key": "/type/edition"},
                    "works": [{"key": "/works/OL1W"}],
                }
            ],
        }
    },
}
keys = list(parse_log([record], False))
print("save moved edition keys:", keys)
assert keys[0] == "/books/OL34239002M"
assert set(keys[1:]) == {"/works/OL1W"}, keys
assert "/works/OL2W" not in keys

# old_docs None -> only top-level key
record_new = {
    "action": "save",
    "data": {
        "changeset": {
            "docs": [
                {
                    "key": "/books/OL1M",
                    "type": {"key": "/type/edition"},
                    "works": [{"key": "/works/OL1W"}],
                }
            ],
            "old_docs": [None],
        }
    },
}
assert list(parse_log([record_new], False)) == ["/books/OL1M"]

# save_many with multiple docs, paired old_docs
record_many = {
    "action": "save_many",
    "data": {
        "changeset": {
            "docs": [
                {"key": "/works/OL1W", "editions": [{"key": "/books/OL1M"}]},
                {"key": "/works/OL2W", "editions": [{"key": "/books/OL2M"}]},
            ],
            "old_docs": [
                {"key": "/works/OL1W", "editions": [{"key": "/books/OL1M"}, {"key": "/books/OL2M"}]},
                None,
            ],
        }
    },
}
keys = list(parse_log([record_many], False))
print("save_many keys:", keys)
assert keys[0] == "/works/OL1W"
assert set(keys[1:2]) == {"/books/OL2M"}, keys
assert "/works/OL2W" in keys

# store.put behavior preserved
sp = {
    "action": "store.put",
    "data": {
        "data": {
            "_key": "ebooks/books/OL5854888M",
            "type": "ebook",
            "book_key": "/books/OL5854888M",
        }
    },
}
assert list(parse_log([sp], False)) == ["/books/OL5854888M"]

print("parse_log OK")
print("ALL TESTS PASSED")
